package com.httymd.client.model;

import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;

import com.httymd.HttymdMod;
import com.httymd.client.NightFuryRenderState;

/**
 * Night Fury model. The shape and the keyframe animations are converted from the original HTTYMD
 * ModelNightFury (see NightFuryModelData, generated by tools/convert_model.py).
 */
public class NightFuryModel extends EntityModel<NightFuryRenderState> {
    public static final ModelLayerLocation LAYER = new ModelLayerLocation(HttymdMod.id("night_fury"), "main");

    private static final float DEG = (float) (Math.PI / 180.0);
    private static final String LEFT = NightFuryModelData.LEFT_PREFIX;

    private final Map<String, ModelPart> parts = new HashMap<>();
    private final ModelPart rootPart;
    private final ModelPart head;
    private final ModelPart[] legs;
    private final ModelPart leftWing;
    private final String[] animated;

    private static final String[] LEG_NAMES = {"leg2", "leg1", "leg3", "leg4"};

    public NightFuryModel(ModelPart root) {
        super(root);
        for (Map.Entry<String, String> e : NightFuryModelData.PATHS.entrySet()) {
            parts.put(e.getKey(), find(root, e.getValue()));
        }
        this.rootPart = parts.get("NightFury");
        this.head = parts.get("head");
        this.leftWing = parts.get(LEFT + "wing");
        this.legs = new ModelPart[LEG_NAMES.length];
        for (int i = 0; i < LEG_NAMES.length; i++) {
            legs[i] = parts.get(LEG_NAMES[i]);
        }

        Set<String> all = new LinkedHashSet<>();
        for (String s : NightFuryModelData.IDLE_PARTS) all.add(s);
        for (String s : NightFuryModelData.FLYING_PARTS) all.add(s);
        this.animated = all.toArray(new String[0]);
    }

    private static ModelPart find(ModelPart root, String path) {
        ModelPart cur = root;
        for (String name : path.split("/")) {
            cur = cur.getChild(name);
        }
        return cur;
    }

    @Override
    public void setupAnim(NightFuryRenderState state) {
        super.setupAnim(state);

        float ms = state.ageInTicks * 50.0f;
        float blend = state.flyBlend;

        // The left wing is the right wing mirrored, exactly like the original WingRenderer.
        leftWing.xScale = -1.0f;

        for (String name : animated) {
            float[] base = NightFuryModelData.BASE.get(name);
            float[] pose = new float[6];
            for (int a = 0; a < 6; a++) {
                float idle = sample(NightFuryModelData.IDLE_PARTS, NightFuryModelData.IDLE_DATA,
                        NightFuryModelData.IDLE_DURATION_MS, name, a, ms, base);
                float fly = sample(NightFuryModelData.FLYING_PARTS, NightFuryModelData.FLYING_DATA,
                        NightFuryModelData.FLYING_DURATION_MS, name, a, ms, base);
                pose[a] = idle + (fly - idle) * blend;
            }
            apply(parts.get(name), pose);
            ModelPart mirror = parts.get(LEFT + name);
            if (mirror != null) {
                apply(mirror, pose);
            }
        }

        // Walking: swing the legs (the original animation data holds them still).
        float walk = 1.0f - blend;
        for (int i = 0; i < legs.length; i++) {
            float swing = (float) Math.cos(state.walkAnimationPos * 0.6662f) * 1.4f * state.walkAnimationSpeed * walk;
            legs[i].xRot += (i % 2 == 0 ? 1 : -1) * swing;
        }

        // Look direction.
        float lookScale = 1.0f - 0.5f * blend;
        head.xRot += state.xRot * DEG * lookScale;
        head.yRot += state.yRot * DEG * lookScale;

        // Pitch the whole body up/down while flying.
        rootPart.xRot += blend * state.xRot * DEG * 0.5f;
    }

    private void apply(ModelPart part, float[] pose) {
        part.x = pose[0];
        part.y = pose[1];
        part.z = pose[2];
        part.xRot = pose[3] * DEG;
        part.yRot = pose[4] * DEG;
        part.zRot = pose[5] * DEG;
    }

    /** Value of one channel of one part at the given time. Falls back to the rest pose if the animation does not touch it. */
    private static float sample(String[] animParts, float[][][] data, int durationMs, String name, int attr, float ms, float[] base) {
        int index = -1;
        for (int i = 0; i < animParts.length; i++) {
            if (animParts[i].equals(name)) {
                index = i;
                break;
            }
        }
        if (index < 0) {
            // base rotations are stored in radians, animation channels in degrees
            return attr >= 3 ? base[attr] / DEG : base[attr];
        }
        float[] frames = data[index][attr];
        int n = frames.length;
        if (n == 1) {
            return frames[0];
        }
        float u = ((ms % durationMs) / durationMs) * n;
        int i1 = (int) Math.floor(u);
        float t = u - i1;
        float p0 = frames[Math.floorMod(i1 - 1, n)];
        float p1 = frames[Math.floorMod(i1, n)];
        float p2 = frames[Math.floorMod(i1 + 1, n)];
        float p3 = frames[Math.floorMod(i1 + 2, n)];
        // periodic Catmull-Rom spline through the keyframes
        return 0.5f * ((2.0f * p1)
                + (-p0 + p2) * t
                + (2.0f * p0 - 5.0f * p1 + 4.0f * p2 - p3) * t * t
                + (-p0 + 3.0f * p1 - 3.0f * p2 + p3) * t * t * t);
    }
}
